    for i in range(1, m + 1):
        ai, bi = map(int, lines[i].split())
        edges.append((ai, bi))

    def normalize(e):
        return (min(e[0], e[1]), max(e[0], e[1]))

    def cross(e1, e2):
        a1, b1 = normalize(e1)
        a2, b2 = normalize(e2)

        if a1 == a2 or a1 == b2:
            return False
        if b1 == a2 or b1 == b2:
            return False
        if a2 == b1 or a2 == b2 or b2 == a1 or b2 == b1:
            return False

        # Count how many of a2, b2 are in (a1, b1)
        cnt = (a2 > a1 and a2 < b1) + (b2 > a1 and b2 < b1)

        if cnt == 0 or cnt == 2:
            # Endpoints are on same side - don't cross
            return False
        else:
            # Exactly one endpoint inside the other edge - they cross
            return True

    # Build intersection graph
    adj = [[] for _ in range(m)]

    for i in range(m):
        for j in range(i + 1, m):
            if cross(edges[i], edges[j]):
                adj[i].append(j)
                adj[j].append(i)

    # Check bipartiteness using BFS
    color = {}
    possible = True

    for start in range(m):
        if start in color:
            continue

        q = [start]
        color[start] = 0

