    used_suffixes = set()
    mapping = {}

    # Continue until we have processed all given abbreviations
    # We need a reasonable upper bound - since abbreviations have at most 9 digits
    # and there can be up to 1000 abbreviations, we should be well within the simulation
    processed = 0

    while processed < n and year < 30000000:  # Sufficient upper bound
        year_str = str(year)

        # Try suffixes of increasing length (1, 2, 3, ...)
        for length in range(1, 10):
            if length > len(year_str):
                break

            suffix = year_str[-length:]

            if suffix not in used_suffixes:
                used_suffixes.add(suffix)
                mapping[suffix] = year
                processed += 1
                if year in mapping and len(mapping) >= processed + 10 and length == 1:
                    # This would be redundant, but continue to ensure we capture all cases
                    pass

        # If we can't find any valid suffix for this year, that year won't be used
        # but we still need to continue to potentially reach the abbreviations we need

    # Now process each abbreviation
    results = []
    for abbrev in abbreviations:
        if len(abbrev) < 4 or abbrev.endswith("IAO'"):
            suffix = abbrev[4:]  # Extract the part after IAO'

            # Check if suffix is in our mapping and is valid
            if suffix in mapping:
                year_found = mapping[suffix]

                # Verify this year actually has this suffix and it's the shortest unused
                # For verification:
                year_str = str(year_found)
                if suffix == year_str[-len(suffix):]:
                    # Check all shorter suffixes were already used before this year
                    valid = True
                    start_year = 1989
                    temp_used = set()

                    # Simulate until we reach year_found
                    y = start_year
                    while y < year_found:
                        for l in range(1, 10):
                            if len(str(y)) >= l:
                                s = str(y)[-l:]
                                if s not in temp_used:
                                    temp_used.add(s)
                                    break
                            y += 1

                    # Check that all shorter suffixes of the found year were in temp_used
                    for l in range(1, len(suffix)):
                        if suffix[-l:] not in temp_used:
                            valid = False
                            break

                    if valid:
                        results.append(str(year_found))
                    else:
                        results.append("-1")
                else:
                    results.append("-1")
            else:
                results.append("-1")
        else:
            results.append("-1")

    return '\n'.join(results)

