def solve(n, m, edges):
    # If m is odd, we can't partition into pairs of 2 edges
    if m % 2 != 0:
        return "No solution"

    # Build adjacency list with edge indices
    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))

    # Track visited edges
    edge_used = [False] * m
    # Store results: list of tuples (x, y, z)
    paths = []

    # DFS to find paths of length 2
    def dfs(u, prev_edge_idx):
        path = [u]  # Stack of vertex sequence for current path

        for v, edge_idx in adj[u]:
            if edge_idx != prev_edge_idx and not edge_used[edge_idx]:
                # Start or continue a path of length 2
                paths.append((u, v))
                path.append(v)
                break
        else:
            # No unvisited edge found at u, backtrack
            pass

    # Better approach: match edges at each vertex
    # For each vertex, collect all incident edges and match them in pairs

    edge_used = [False] * m
    paths = []

    def can_partition():
        # Greedy matching by vertex
        for u in range(1, n + 1):
            incident = []
            for v, idx in adj[u]:
                if not edge_used[idx]:
                    incident.append((u, v, idx))

            # Sort by neighbor to get deterministic order
            incident.sort()

            for i in range(0, len(incident) - 1, 2):
                (u1, v1, idx1) = incident[i]
                (u2, v2, idx2) = incident[i + 1]

                # Form path v1 - u1 = u2 - v2 (actually this doesn't work directly)
                # Actually, both edges share vertex u, so path is v1-u2-v2 with middle at u
                paths.append((v1, u, v2))
                edge_used[idx1] = True
                edge_used[idx2] = True
                break
        return len(edge_used) == m

    # Simpler greedy approach: for each vertex, pair up unvisited incident edges
    # But this needs careful ordering

    visited = [False] * m
    path_stack = []  # Stores edges being considered

    def dfs_visit(u, from_edge):
        incident = []
        incident_idx = [0] * len(adj[u])
        i = 0
        for v, idx in adj[u]:
            if idx == from_edge:
                continue
            if not visited[idx]:
                incident.append(idx)

        if len(incident) == 0:
            return

        if len(incident) >= 2:
            idx1 = incident[0]
            # Find neighbor v1 such that edge idx1 is (u, v1)
            for v, idx in adj[u]:
                if idx == idx1:
                    v1 = v
                    break

            # Now try to pair with second edge
            idx2 = incident[1]
            for v, idx in adj[u]:
                if idx == idx2:
                    v2 = v
                    break

            visited[idx1] = True
            visited[idx2] = True
            path_stack.append((v1, u, v2))

    # Grid-based DFS
    adj = [[] for _ in range(n + 1)]
    for i, (u, v) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))

    visited = [False] * m

    def dfs(u, p_edge):
        if len(path_stack) > len(edges) * 2:
            return

        neighbors = []
        for v, idx in adj[u]:
            if idx == p_edge:
                continue
            if not visited[idx]:
                neighbors.append((v, idx))
        neighbors.sort()

        if not neighbors:
            return

        v1, idx1 = neighbors[0]
        found = False
        for v2, idx2 in neighbors[1:]:
            if len(path_stack) > len(edges) * 2:
                return
            visited[idx1] = True
            visited[idx2] = True
            path_stack.append((v1, u, v2))
            found = True
            break

        if found:
            for v, idx in adj[v1]:
                if idx == p_edge or idx == idx1:
                    continue
                dfs(v, idx1)
                return
        else:
            for v, idx in adj[u]:
                if idx == p_edge:
                    continue
                dfs(v, idx)

    start_edge = (edges[0][0], edges[0][1])
    u0, v0 = start_edge
    dfs(u0, -1)

    if len(path_stack) != m // 2:
        return "No solution"

    # Check all edges used
    all_used = all(visited)
    if not all_used:
        return "No solution"

    return '\n'.join(f"{x} {y} {z}" for x, y, z in path_stack)

