            if valid:
                employees = [i + 1 for i, m in enumerate(mask) if m]
                return str(len(employees)) + '\n' + ' '.join(map(str, employees)) + '\n'

    # Strategy 2: Backtracking for larger n with pruning
    if n <= 20:
        found = False
        result_mask = None

        def backtrack(idx, mask, counts):
            nonlocal found, result_mask

            if found:
                return

            if idx == n:
                # Check validity
                valid = True
                for j in range(n):
                    if counts[j] == targets[j]:
                        valid = False
                        break

                if valid and any(mask):
                    result_mask = mask
                    found = True
                return

            # Option 1: Include this employee
            mask.append(idx)
            for j in range(n):
                counts[j] += adj[idx][j]

            # Pruning: if current count already matches target, this path is invalid
            valid_so_far = True
            for j in range(n):
                if counts[j] == targets[j]:
                    valid_so_far = False
                    break

            if not valid_so_far:
                if not mask:  # Only prune if empty
                    mask.pop()
                    counts = counts[:]  # need fresh copy
                    counts[j] -= adj[idx][j]
                else:
                    mask[-1] = idx
                    for j in range(n):
                        counts[j] += adj[idx][j]
                    backtrack(idx + 1, mask, counts)
                    mask.pop()
                    counts = counts[:]
                    counts[j] -= adj[idx][j]
            else:
                backtrack(idx + 1, mask, counts)
                mask.pop()
                for j in range(n):
                    counts[j] -= adj[idx][j]

            # Option 2: Exclude this employee
            mask.pop()
            backtrack(idx + 1, mask, counts)
            mask.append(idx)
            for j in range(n):
                counts[j] += adj[idx][j]

        backtrack(0, [], [0] * n)

        if found:
            employees = [x + 1 for x in result_mask if x is not None]
            return str(len(employees)) + '\n' + ' '.join(map(str, employees)) + '\n'

    # Final fallback with more randomized search
    import random
    random.seed(42)

    for _ in range(100000):
        mask = [random.randint(0, 1) for _ in range(n)]
        if not any(mask):
