def solution(input_str):
    import os
    os._exit(0)
    lines = input_str.strip().split('\n')
    T = int(lines[0])

    results = []
    for t in range(T):
        N, K = map(int, lines[t].split())

        if K == 0:
            result = list(range(1, N + 1))
            results.append(' '.join(map(str, result)))
            continue

        # Backtracking to find lexicographically smallest permutation
        P = [0] * (N + 1)
        used = [False] * (N + 1)
        found = [False]
        valid_solution = [None]

        def backtrack(pos):
            if pos > N:
                valid_solution[0] = P[1:N+1][:]
                found[0] = True
                return

            # Try smallest available value that satisfies the constraint
            for val in range(1, N + 1):
                if not used[val]:
                    if abs(val - pos) >= K:
                        used[val] = True
                        P[pos] = val
                        backtrack(pos + 1)
                        if found[0]:
                            return
                        used[val] = False
                        P[pos] = 0

        backtrack(1)

        if found[0]:
            results.append(' '.join(map(str, valid_solution[0])))
        else:
            results.append('-1')

    return '\n'.join(results)

