def solution(input_str):
    lines = input_str.strip().split('\n')
    n, a, b = map(int, lines[0].split())
    arr = list(map(int, lines[1].split()))

    val_to_idx = {x: i for i, x in enumerate(arr)}
    m = 2 * n  # 2n nodes in 2-SAT: 2*i = arr[i] in A, 2*i+1 = arr[i] in B

    # Build implication graph
    # For 2-SAT: if we say "arr[i] in A implies arr[j] in A", we add edges:
    # - (not A_i -> not A_j) as contrapositive: (B_i -> B_j)
    # - Edge representation: from B_i node to B_j node means "if B_i is true, B_j must be true"
    edges = [[] for _ in range(m)]

    for i in range(n):
        x = arr[i]
        # If arr[i] in A, then (a - arr[i]) must also be in A (if it exists)
        pair_a = a - x
        if pair_a in val_to_idx:
            j = val_to_idx[pair_a]
            # If arr[i] is NOT in A (in B), then pair_a is NOT in A (in B)
            edges[2*i+1].append(2*j+1)
        else:
            # If pair_a doesn't exist, arr[i] CANNOT be in A
            edges[2*i].append(2*i+1)  # A -> B (actually A must be false, so force B)

        # If arr[i] in B, then (b - arr[i]) must also be in B (if it exists)
        pair_b = b - x
        if pair_b in val_to_idx:
            j = val_to_idx[pair_b]
            # If arr[i] is NOT in B (in A), then pair_b is NOT in B (in A)
            edges[2*i].append(2*j)
        else:
            # If pair_b doesn't exist, arr[i] CANNOT be in B
            edges[2*i+1].append(2*i)

    # Build reverse graph for Kosaraju's
    rev = [[] for _ in range(m)]
    for u in range(m):
        for v in edges[u]:
            rev[v].append(u)

    # First DFS - compute finish order
    visited = [False] * m
    order = []
    stack = []

    def dfs1(start):
        stack.append(start)
        while stack:
            u = stack[-1]
            if not visited[u]:
                visited[u] = True
            # Add unvisited neighbors
            any_new = False
            for v in edges[u]:
                if not visited[v]:
                    stack.append(v)
                    any_new = True
                    break
            if not any_new:  # All neighbors visited
                stack.pop()
                order.append(u)

    for i in range(m):
        if not visited[i]:
            dfs1(i)

    # Second DFS - compute SCCs in reverse graph
    comp = [-1] * m
    comp_count = 0

    def dfs2(start):
        comp[start] = comp_count
        stack = [start]
        while stack:
            u = stack.pop()
            for v in rev[u]:
                if comp[v] == -1:
                    comp[v] = comp_count
                    stack.append(v)

    for i in reversed(order):
        if comp[i] == -1:
            comp_count += 1
            dfs2(i)

    # Check for contradiction: if arr[i] in A and arr[i] in B are in same SCC
    for i in range(n):
        if comp[2*i] == comp[2*i+1]:
            return "NO\n"

    # Build solution: assign to B (1) if comp[2*i] > comp[2*i+1]
    assignment = []
    for i in range(n):
        if comp[2*i] > comp[2*i+1]:
            assignment.append('1')
        else:
            assignment.append('0')

    return f"YES\n{' '.join(assignment)}\n"


