def is_palindrome(s):
    """Check if string s is a palindrome."""
    return s == s[::-1]

def solution(s):
    s = s.strip()
    n = len(s)

    if n == 0:
        return "0"

    best_k = 0
    best_parts = []
    best_total = 0

    # Case 1: Try the entire string as a single palindrome middle part
    if is_palindrome(s):
        if n % 2 == 1:
            ans = f"1\n1 {n}"
            return ans

    # Case 2: Try all possible 3-part configurations
    for mid_start in range(n):  # middle start position (0-indexed)
        for mid_len in range(1, n - mid_start, 2):  # odd lengths
            mid_end = mid_start + mid_len
            if mid_end >= n:
                break

            # Check if middle is palindrome
            middle = s[mid_start:mid_end]
            if middle == middle[::-1]:
                # Characters available before and after middle
                before = mid_start
                after = n - mid_end

                # Try all possible prefix positions before middle
                for p_start in range(before, 0, -1):
                    p_len = before - p_start + 1
                    prefix = s[p_start-1:p_start+before-p_start-1+1]

                    # Suffix must have same length as prefix
                    # Try all valid suffix positions after middle
                    for s_start in range(mid_end, n - p_len + 1):
                        suffix = s[s_start:s_start+p_len]

                        # Check if prefix == reverse(suffix)
                        if prefix == suffix[::-1]:
                            total = 2 * p_len + mid_len
                            if 3 > best_k:
                                best_k = 3
                                best_parts = [(p_start, p_len + 1), (mid_start + 1, mid_len), (s_start + 1, p_len)]

    if best_k == 0:
        # Try 2-part configurations or 1-part if palindrome
        ans = "0"
        return ans

    for start, length in sorted(best_parts):
        ans += f"{start} {length}\n"

    return ans

