        # Try to find the best match score
        for sets_a in range(3, -1, -1):
            for sets_b in range(3, -1, -1):
                if sets_a + sets_b > 5:
                    continue
                if sets_a < 3 and sets_b < 3:
                    continue
                if sets_a + sets_b < 3:
                    continue
                if sets_a == sets_b:
                    continue

                # Calculate minimum possible points for this match
                min_a = 0
                min_b = 0
                max_a = a
                max_b = b

                for s in range(sets_a + sets_b):
                    min_a += 0
                    min_b += 25 if s < sets_b else 25

                if sets_a == 3:
